local a={}local function b(c)c=c%360;if c<0 then c=c+360 end;return c end;local function d(e,f)return(e-f+180)%360-180 end;function a.solve(g,h)if type(g)~="table"or type(h)~="table"then return nil end;if type(g.x)~="number"or type(g.z)~="number"then return nil end;if type(h.x)~="number"or type(h.z)~="number"then return nil end;local i,j=h.x-g.x,h.z-g.z;local k=b(math.deg(math.atan2(i,-j)))local l=math.sqrt(i*i+j*j)local m=nil;if type(g.heading)=="number"then m=d(k,g.heading)end;local n=nil;if type(h.y)=="number"and type(g.baroY)=="number"then n=h.y-g.baroY end;return{bearing=k,distanceH=l,relBearing=m,altDelta=n}end;return a